/* FIL12A filler12a renderer + review-board protocol (aptos-* messages, same as the other V4 pages). Generated by v4/filler12a/lib/fl-lib.cjs.
   Every visible word comes from copy-data.js and is edited in place through ../inline-edit.js. Display-only helpers never change the stored text. */
(()=>{'use strict';
const DATA=window.PAGE_COPY;
if(!DATA||!DATA.locales||!DATA.locales.KO){document.documentElement.dataset.reviewError='copy-data missing';return;}
const KEYS=Object.keys(DATA.locales.KO);
/* 2026-11-19 language versions (v4/filler12a/lib/fl-i18n.cjs): <html lang> drives the language fonts and layout rules in the -i18n.css (:lang()); the
   Google font of the language is added here (same as combo12a.js / cerf12.js). Korean renders exactly as before. */
const LANG={KO:'ko',EN:'en',JP:'ja',CN:'zh-CN',TW:'zh-TW',TH:'th',HK:'zh-HK'};
const FONT_FAMILY={JP:'Noto Sans JP',CN:'Noto Sans SC',TW:'Noto Sans TC',HK:'Noto Sans TC',TH:'Noto Sans Thai'};
const CJK={JP:1,CN:1,TW:1,HK:1},SEGS={};
const qs=new URLSearchParams(location.search);
let locale=String(qs.get('lang')||'KO').toUpperCase();if(!DATA.locales[locale])locale='KO';
let fields={...DATA.locales[locale]};
let editable=false,editMode=false,lastHeight=0;
const root=document.documentElement;
if(qs.get('capture')==='1')root.classList.add('is-capture');
function setFonts(){let l=document.getElementById('locale-fonts');const family=FONT_FAMILY[locale];if(!family){if(l)l.remove();return;}if(!l){l=document.createElement('link');l.id='locale-fonts';l.rel='stylesheet';document.head.append(l);l.addEventListener('load',()=>document.fonts.ready.then(()=>{fit();report();}));}const href='https://fonts.googleapis.com/css2?family='+family.replace(/ /g,'+')+':wght@400;500;600;700;800;900&display=swap';if(l.getAttribute('href')!==href)l.setAttribute('href',href);}
function reply(message){if(parent!==window)parent.postMessage(message,location.origin);}
const IE=window.BBInlineEdit?window.BBInlineEdit.create({doc:document,raw:k=>fields[k]??'',send:m=>reply(m),refit:()=>{fit();report();},rerender:()=>render()}):null;
function report(){const main=document.querySelector('main');if(!main)return;const h=Math.max(300,Math.min(25000,Math.ceil(main.getBoundingClientRect().height)));if(h===lastHeight)return;lastHeight=h;reply({type:'aptos-size',height:h});}
/* money: the number large, the unit small */
function setMoney(el,v){el.textContent='';const m=/^(\D*?)(\d[\d,.]*)(.*)$/.exec(v||'');if(!m){el.textContent=v||'';return;}
 if(m[1]){const p=document.createElement('span');p.className='u pre';p.textContent=m[1];el.append(p);}
 const n=document.createElement('span');n.className='n';n.textContent=m[2];el.append(n);
 if(m[3]){const s=document.createElement('span');s.className='u';s.textContent=m[3];el.append(s);}}
/* options: each part stays on one line, breaks only at ' + ' (the separators stay as text) */
/* 2026-11-19 language versions (as combo12a.js): the CN / JP copy may join the parts with a full-width '＋' and use full-width brackets; it splits before every
   '＋' outside brackets too and the '＋' stays as the separator text (the Korean copy has neither, so it is set exactly as before) */
function topSplit(v){const parts=[],seps=[];let depth=0,start=0;for(let i=0;i<v.length;i++){const c=v[i];if(c==='('||c==='['||c==='（'||c==='［')depth++;else if((c===')'||c===']'||c==='）'||c==='］')&&depth)depth--;else if(!depth&&v.startsWith(' + ',i)){parts.push(v.slice(start,i));seps.push(' + ');start=i+3;i+=2;}else if(!depth&&c==='＋'){parts.push(v.slice(start,i));seps.push('＋');start=i+1;}}parts.push(v.slice(start));return {parts,seps};}
function setParts(el,v){el.textContent='';v=v||'';const {parts,seps}=topSplit(v);parts.forEach((p,i)=>{if(i)el.append(document.createTextNode(seps[i-1]));const c=document.createElement('span');c.className='seg';if(locale==='TH')appendKept(c,p);else c.textContent=p;el.append(c);});} /* 2026-11-19 TH: its loanwords and number + unit stay whole inside a part (KEEP_TH) */
function setHours(el,v){el.textContent='';const m=/^(.*\S)(\s+)(\d{1,2}:\d{2}\s*[\u2013\u2014~-]\s*\d{1,2}:\d{2}.*)$/.exec(v||'');if(!m){el.textContent=v||'';return;}
 const d=document.createElement('span');d.className='hd';d.textContent=m[1];const t=document.createElement('span');t.className='ht';t.textContent=m[3];el.append(d,document.createTextNode(m[2]),t);}
const GUARD='.p-lead,.q-ans,.blk-d,.st-d,.inf-n,.ask-d,.care [data-copy],.src,.notes [data-copy],.ad,.ab-lead [data-copy],.dr-quote,.way-addr > [data-copy],.c4-note [data-copy],.prod-note [data-copy],.grp-d,.h-sub [data-copy],.blk-n,.ab-title';
/* 2026-11-19 language versions: KEEP also keeps the international phone number, a chat ID and the Latin names of the language copy whole
   (v4/filler12a/lib/fl-i18n.cjs LANG_KEEP; no Korean copy has them, the build checks it) */
const KEEP=/(\+?82[ -]\d{1,2}[ -]\d{3,4}-\d{4}|@[\w.\-]+|Beauty Blossom(?: Clinic)?|Beautyblossom00|Signature Filler|Restylane (?:Kysse|Soft|Eyelight|Lyft|Volyme|Defyne|Refyne)|Belotero (?:Soft|Balance|Volume|Intense)|Juvederm (?:Volbella|Volift|Voluma)|Medione Medical Center|MediOne Medical Center|Yanghwa-ro|Mapo-gu|BEAUTY::BLOSSOM|02-336-7511|'뷰티블라썸의원'|VAT 10%|스윗 입술필러|내츄럴 애교필러|다크서클 눈밑필러|커스텀 코필러|애플존 필러|아띠에르 · 리쥬비엘|레스틸렌 · 벨로테로|의료용 실\(PDO\)|1cc당|히알루론산\(HA\)|15~20분)/g;
/* 2026-11-19 TH (as combo12a.js): Thai loanwords the browser's Thai dictionary does not know break between their syllables ('ฟิล|เลอร์'), and so do a few
   compounds and the director's name; they stay whole, and so do a number and its unit ('1 cc', '200,000 วอน', '20:00 น.') and an exit / line / floor / house
   number ('ทางออก 3'). Only the Thai copy is set with this list (KEEP_TH = KEEP + these); Korean, CN and JP use KEEP */
const KEEP_TH=new RegExp(KEEP.source+'|ฟิลเลอร์|โปรแกรม|โปรโมชั่น|ดอลลี่อาย|ไฮยาลูโรนิก|โบท็อกซ์|สกินโบท็อกซ์|เหมาะสม|ผู้อำนวยการ|สุดสัปดาห์|ขั้นตอน|อี กอนโฮ|ชุ่มชื้น|\\d[\\d,.:]*\\s(?:cc|ครั้ง|บริเวณ|เท่า|นัด|กลุ่ม|วอน|น\\.|เส้น|กล่อง|ขวด|ช็อต|พัลส์)|(?:ทางออก|สาย|ชั้น|เลขที่)\\s\\d+','g');
/* 2026-11-19 JP: the katakana loanwords stay whole and a line breaks between them (v4/filler12a/lib/fl-i18n.cjs JP_KEEP); only the Japanese copy */
const KEEP_JP=new RegExp(KEEP.source+'|ビューティーブロッサム|シグネチャー|スキンブースター|スキンボトックス|エラボトックス|ボトックス|フェイスライン|スマイルライン|オーダーメイド|カウンセリング|キャンペーン|スイート|リップ|ナチュラル|デザイン|フィラー|アティエル|リジュビエル|レスチレン|ベロテロ|ミジュコ|ヒアルロン|ジュベルック|ジュビダーム|レディエッセ|ポテンツァ|ソフウェーブ|ポンピング|ハイブリッド|ボリューム|スキン|メディワン|メディカル|センター|スウェーデン|プレミアム|コラーゲン|バイオ|リモデリング|カルシウム|ハイドロキシ|アパタイト|リフトアップ|サーマクール|ウルセラ|ボルニューマ|シュリンク|リジュラン|リセット|シークレット|レシピ|ハリケア|リノベーション|ゼオミン|ハンドピース|エネルギー|バランス|ディテール|コンビ|ライン|プラン|ショット|アイライト|アクセス|アイドル|ベラスト|フランス|サウナ|イ・ゴンホ|イ・ゴノ','g');
/* 2026-11-19 CN: a few Chinese words stay whole so a title line breaks between words (v4/filler12a/lib/fl-i18n.cjs CN_KEEP); only the Chinese copy */
const KEEP_CN=new RegExp(KEEP.source+'|丽朵皮肤科|招牌定制|玻尿酸|水光针|水光肉毒|肉毒|美版超声刀|超声刀|热玛吉|黄金微针|乔雅登|乔雅露|瑞蓝|保柔缇|瑞得喜|索夫波|微笑线|法令纹|苹果肌|卧蚕|颈纹|下颌线|全脸|锁骨|精灵耳|线雕鼻|精选|组合|优惠|活动','g');
const keepRe=()=>locale==='TH'?KEEP_TH:locale==='JP'?KEEP_JP:locale==='CN'?KEEP_CN:KEEP;
function appendKept(el,s){let last=0;const R=keepRe();R.lastIndex=0;for(const m of s.matchAll(R)){if(m.index>last)el.append(document.createTextNode(s.slice(last,m.index)));let e=m.index+m[0].length;while(e<s.length&&/[，。、：；！？）」』]/.test(s[e]))e++; /* 2026-11-19: Chinese / Japanese punctuation right after a kept name stays with it (it may not start a line); Korean copy has none */
 const k=document.createElement('span');k.className='nw';k.textContent=s.slice(m.index,e);el.append(k);last=e;}if(last<s.length)el.append(document.createTextNode(s.slice(last)));}
/* 2026-11-19 Chinese / Japanese (same as combo12a.js): the last three characters stay together, grown back to the start of their word (a '・' break or
   Intl.Segmenter) so a short line never splits a word; at most 5 characters (punctuation aside). Thai has no guard (dictionary breaks). */
function cjkCut(v,cut){const core=(i)=>v.slice(i).replace(/[。！？，、）)]+$/u,'').length;
 const sep=Math.max(v.lastIndexOf('・'),v.lastIndexOf('·'));if(sep>0&&sep+1<v.length&&core(sep+1)>=2&&core(sep+1)<=5)return sep+1;
 let seg=SEGS[locale];if(seg===undefined){try{seg=SEGS[locale]=new Intl.Segmenter(LANG[locale],{granularity:'word'});}catch(e){seg=SEGS[locale]=null;}}if(!seg)return cut;
 let start=0,end=v.length;for(const g of seg.segment(v)){if(g.index>cut){end=g.index;break;}start=g.index;}
 if(start===cut)return cut;if(start>0&&core(start)<=5)return start;return end<v.length?end:-1;}
/* flex / grid boxes turn every text piece into its own item (gaps, trimmed spaces), so they keep their text whole */
const guardable=(el)=>!/flex|grid/.test(getComputedStyle(el).display);
/* the guard only for text with Chinese characters or kana; a Latin-only line is set as on the Korean page */
const HAN=/[\u3040-\u30ff\u3400-\u9fff\uf900-\ufaff]/;
function setText(el,v){
 if(el.classList.contains('money')){setMoney(el,v);return;}
 if(el.classList.contains('popt')||el.classList.contains('prod-n')){setParts(el,v);return;}
 if(el.matches('.hrs [data-copy]')){setHours(el,v);return;}
 const KR=keepRe();KR.lastIndex=0;const kept=!!v&&KR.test(v);KR.lastIndex=0;
 /* Chinese / Japanese: every text keeps its last word together (the Korean list GUARD stays as it was) */
 if(!v||(!el.matches(GUARD)&&!(CJK[locale]&&HAN.test(v)&&guardable(el)))){if(kept){el.textContent='';appendKept(el,v);}else el.textContent=v;return;}
 /* no lonely last word: the last two words stay together */
 let m=null;
 if(locale==='TH')m=null;
 else if(!CJK[locale])m=v.match(/(\S+[ \t]+\S+)$/);
 /* Chinese / Japanese guard only in boxes whose text flows inline: in a flex / grid box the kept tail would become its own item with a gap before it */
 else if(HAN.test(v)&&guardable(el)){m=v.match(/([^\s]{3}[。！？，、）)]*)$/u);if(m&&m[1].length<v.length){const c=cjkCut(v,v.length-m[1].length);m=c>0?[null,v.slice(c)]:null;}}
 if(m){let cut=v.length-m[1].length;for(const k of v.matchAll(KR))if(cut>k.index&&cut<k.index+k[0].length)cut=k.index;m=cut>0?[null,v.slice(cut)]:null;}
 if(!m||m[1].length>=v.length){el.textContent='';appendKept(el,v);return;}
 const tail=document.createElement('span');tail.className='nw';tail.textContent=m[1];el.textContent='';appendKept(el,v.slice(0,v.length-m[1].length));el.append(tail);}
function isPhone(){const m=document.querySelector('main');return !!m&&m.clientWidth<=600;}
function fitTo(el,limit,min){el.style.removeProperty('--fit');for(let f=1,i=0;i<40&&el.scrollWidth>limit+1&&f>min;i++){f-=.02;el.style.setProperty('--fit',f.toFixed(3));}return el.scrollWidth<=limit+1;}
function fitLines(el,lines,min){el.style.removeProperty('--fit');const lh=()=>parseFloat(getComputedStyle(el).lineHeight)||0;for(let f=1,i=0;i<30&&(el.getBoundingClientRect().height>lh()*lines+2||el.scrollWidth>el.clientWidth+1)&&f>min;i++){f-=.02;el.style.setProperty('--fit',f.toFixed(3));}}
function fit(){
 for(const el of document.querySelectorAll('.h-title')){fitTo(el,el.parentElement.clientWidth*.98,.6);}
 for(const el of document.querySelectorAll('.pt-main')){const t=el.closest('.p-title');const c=t.querySelector('.pt-cont');fitTo(el,t.clientWidth-(c?c.offsetWidth+16:0),.6);}
 for(const el of document.querySelectorAll('.q-title')){fitLines(el,2,.72);}
 for(const el of document.querySelectorAll('.ab-title')){fitLines(el,2,.74);}
 for(const el of document.querySelectorAll('.seal .sl')){const p=el.parentElement;fitTo(el,p.clientWidth*.86,.55);}
}
function render(){
 root.lang=LANG[locale]||'ko';root.dataset.locale=locale;setFonts();
 root.classList.toggle('is-editable',editable);root.classList.toggle('is-editmode',editable&&editMode);
 for(const el of document.querySelectorAll('[data-copy]')){
  if(IE&&IE.holds(el))continue;
  const v=fields[el.dataset.copy]??'';setText(el,v);
  const empty=!String(v).trim();el.classList.toggle('is-empty',empty);
  if(el.hasAttribute('data-optional'))el.hidden=empty&&!(editable&&editMode);
 }
 for(const g of document.querySelectorAll('[data-optional-group]'))g.hidden=[...g.querySelectorAll('[data-optional]')].every(e=>e.hidden);
 for(const el of document.querySelectorAll('[data-alt]'))el.alt=fields[el.dataset.alt]??'';
 const CH=(DATA.channels&&DATA.channels[locale])||null;
 for(const a of document.querySelectorAll('a[data-link]')){const n=a.dataset.link;const href=CH&&(n in CH)?CH[n]:(DATA.links&&DATA.links[n]);if(href)a.href=href;else a.removeAttribute('href');if(n!=='phone'){a.target='_blank';a.rel='noopener noreferrer';}}
 for(const img of document.querySelectorAll('img[data-qr]')){const q=CH&&CH.qr;if(q&&img.getAttribute('src')!==q)img.setAttribute('src',q);}
 /* 2026-11-19 language versions (CRF12 / THM12 / ONE12 / CMB12A rule): the hero button line names the country's chat channel (TH 'Line: @beautyblossom_th',
    JP 'LINE：@beautyblossom_jp', CN '预约咨询：官方微信 Beautyblossom00'); it shows the consult icon and opens that channel (the booking link) instead of the
    phone. Korean and phone-number lines keep the phone icon and tel: */
 for(const a of document.querySelectorAll('a.cta-a[data-link="phone"]')){const sp=a.querySelector('[data-copy]'),v=String((sp&&fields[sp.dataset.copy])??''),chat=locale!=='KO'&&/微信|WeChat|WhatsApp|LINE/i.test(v);
  const img=a.querySelector('img.cta-ico');if(img){if(chat&&!img.dataset.src0)img.dataset.src0=img.getAttribute('src');const pic=chat?'assets/icons/consult.webp':(img.dataset.src0||img.getAttribute('src'));if(img.getAttribute('src')!==pic)img.setAttribute('src',pic);}
  const b=chat&&CH&&CH.booking;if(b){a.href=b;a.target='_blank';a.rel='noopener noreferrer';}else{a.removeAttribute('target');a.removeAttribute('rel');}}
 /* the booking-box phone line (…_ab_phone) may later hold the country's chat ID instead of a number (edited on the board); then the chat icon and the
    booking link replace the phone icon and tel: (LIG12 / ONE12 / CMB12A rule). Korean always holds the number: nothing changes there. */
 const isId=(v)=>!!v&&!/^\+?\d[\d\s\-().]*$/.test(v);
 for(const p of document.querySelectorAll('.bk-phone')){const sp=p.querySelector('[data-copy]'),v=String((sp&&fields[sp.dataset.copy])??'').trim(),id=locale!=='KO'&&isId(v);p.classList.toggle('is-id',id);
  const img=p.querySelector('img.bk-ico');if(img){if(id&&!img.dataset.src0)img.dataset.src0=img.getAttribute('src');const pic=id?'assets/icons/consult.webp':(img.dataset.src0||img.getAttribute('src'));if(img.getAttribute('src')!==pic)img.setAttribute('src',pic);}
  const a=p.querySelector('a[data-link]');if(a){if(id){const b=(CH&&CH.booking)||(DATA.links&&DATA.links.booking);if(b)a.href=b;a.target='_blank';a.rel='noopener noreferrer';}else{a.removeAttribute('target');a.removeAttribute('rel');}}}
 const GM=(DATA.gmap&&DATA.gmap[locale])||null;
 for(const el of document.querySelectorAll('[data-gmap]')){const u=GM&&GM[el.dataset.gmap];if(!u)continue;const a=el.tagName==='SOURCE'?'srcset':'src';if(el.getAttribute(a)!==u)el.setAttribute(a,u);}
 for(const w of document.querySelectorAll('[data-bk-alt]')){const lab=w.querySelector('[data-copy]');w.hidden=!String((lab&&fields[lab.dataset.copy])??'').trim()&&!(editable&&editMode);}
 document.title=[fields.fa_title||'',fields.fa_brand||'BEAUTY BLOSSOM'].join(' \u00b7 ');
 if(IE)IE.sync(editable);
 requestAnimationFrame(()=>{fit();report();});
 if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>{fit();report();});
 root.dataset.reviewReady='true';
}
window.addEventListener('message',event=>{
 if(event.source!==parent||event.origin!==location.origin)return;
 const msg=event.data;if(!msg||typeof msg!=='object')return;
 if(msg.type==='aptos-data'&&DATA.locales[msg.locale]&&msg.fields&&typeof msg.fields==='object'){
  if(msg.locale!==locale){locale=msg.locale;fields={...DATA.locales[locale]};}
  for(const k of KEYS)if(typeof msg.fields[k]==='string')fields[k]=msg.fields[k];
  editable=msg.editable===true;editMode=msg.editMode===true;render();
 }else if(msg.type==='aptos-save-result'){if(IE)IE.saveResult(msg);}
 else if(msg.type==='aptos-start-edit'&&typeof msg.field==='string'){if(IE)IE.start(msg.field);}
});
window.addEventListener('resize',()=>{fit();report();});
if(document.fonts&&document.fonts.addEventListener)document.fonts.addEventListener('loadingdone',()=>{fit();report();});
const main=document.querySelector('main');
if(main&&'ResizeObserver' in window)new ResizeObserver(report).observe(main);
for(const img of document.images){if(!img.complete){img.addEventListener('load',report,{once:true});img.addEventListener('error',report,{once:true});}}
render();
window.__FL12__={get locale(){return locale;},get editable(){return editable;},get editMode(){return editMode;},get inline(){return !!IE;},keys:KEYS};
reply(IE?{type:'aptos-ready',inline:true}:{type:'aptos-ready'});
})();
